let user = { name: 'Alice' };

// 1. 일반 Map (강한 참조)
const strongMap = new Map();
strongMap.set(user, 'Data');

// 2. WeakMap (약한 참조)
const weakMap = new WeakMap();
weakMap.set(user, 'Secret');

// user 객체 삭제 (참조 끊기)
user = null;

// 결과:
// strongMap은 여전히 Alice를 잡고 있음 (메모리 해제 안 됨)
// weakMap은 Alice를 놓아줌 (GC 수거됨)
